cd /workspace && python3 - <<'PY'
# Independent structural check: does any file outside .evimed-sources reference GSE2553?
import os
hits=[]
for root,dirs,files in os.walk('/workspace'):
    dirs[:]=[d for d in dirs if d not in ('.git','node_modules')]
    for f in files:
        p=os.path.join(root,f)
        try:
            with open(p,'rb') as fh: b=fh.read()
        except Exception: continue
        if b'GSE2553' in b: hits.append(p)
print("files containing 'GSE2553':",len(hits))
for h in hits[:20]: print("  ",h)
PY
